from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from app.config import settings


router = APIRouter(tags=["support-ui"])


@router.get("/support", response_class=HTMLResponse)
async def support_dashboard() -> HTMLResponse:
    if not settings.support_ui_enabled:
        return HTMLResponse("Support UI is disabled.", status_code=404)
    html = _HTML.replace(
        "__POLL_MS__", str(max(1, settings.support_queue_poll_seconds) * 1000)
    ).replace("__CSRF_COOKIE__", settings.support_csrf_cookie_name)
    return HTMLResponse(html)


_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Customer Support</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#172033;background:#f5f7fb}
*{box-sizing:border-box}body{margin:0}.hidden{display:none!important}.login-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:#f5f7fb}.login-card{width:min(420px,100%);background:#fff;border:1px solid #e4e9f2;border-radius:16px;padding:28px;box-shadow:0 12px 34px rgba(20,35,60,.08)}.login-card h1{margin:0 0 6px;font-size:22px}.login-card p{margin:0 0 20px;color:#748098;font-size:14px}.field{margin:12px 0}.field label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}.field input,.field select,.composer textarea{width:100%;border:1px solid #cfd7e6;border-radius:10px;padding:11px;font:inherit}.login-card .btn{width:100%;margin-top:8px}.login-error{margin-top:12px;padding:10px 12px;background:#ffe9eb;color:#8a1f2a;border-radius:9px;display:none}.app{display:grid;grid-template-columns:360px minmax(0,1fr);height:100vh}.sidebar{background:#fff;border-right:1px solid #e4e9f2;display:flex;flex-direction:column;min-width:0}.brand{padding:20px;border-bottom:1px solid #e4e9f2}.brand h1{font-size:18px;margin:0 0 4px}.muted{color:#748098;font-size:13px}.staffbar{padding:12px 20px;border-bottom:1px solid #e4e9f2;display:flex;gap:8px;align-items:center;justify-content:space-between}.tabs{padding:10px;display:flex;flex-wrap:wrap;gap:6px;border-bottom:1px solid #e4e9f2}.tabs button,.btn{border:0;border-radius:9px;padding:9px 11px;background:#edf1f7;cursor:pointer;font-weight:600}.tabs button.active,.btn.primary{background:#172033;color:#fff}.btn.danger{background:#a72b37;color:#fff}.btn:disabled{opacity:.5;cursor:not-allowed}.queue{overflow:auto;flex:1}.ticket-row{padding:14px 16px;border-bottom:1px solid #edf1f7;cursor:pointer}.ticket-row:hover,.ticket-row.active{background:#f0f4fb}.ticket-row .top{display:flex;justify-content:space-between;gap:8px}.ticket-row strong{font-size:14px}.badge{font-size:11px;border-radius:999px;background:#eaf0f9;padding:4px 7px;white-space:nowrap}.summary{font-size:13px;color:#59657c;margin-top:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.main{display:grid;grid-template-rows:auto 1fr auto;min-width:0}.header{background:#fff;border-bottom:1px solid #e4e9f2;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;gap:10px}.actions{display:flex;gap:7px;flex-wrap:wrap}.content{display:grid;grid-template-columns:minmax(0,1fr) 320px;min-height:0}.conversation{overflow:auto;padding:18px}.context{background:#fff;border-left:1px solid #e4e9f2;padding:18px;overflow:auto}.context h3{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:#748098;margin:18px 0 8px}.context p{margin:5px 0;font-size:14px;word-break:break-word}.msg{max-width:78%;padding:10px 12px;border-radius:12px;margin:8px 0;background:#fff;border:1px solid #e3e8f1}.msg.out{margin-left:auto;background:#eaf1ff}.msg.context-msg{opacity:.75;border-style:dashed}.meta{font-size:11px;color:#7e899d;margin-top:5px}.event{margin:8px auto;max-width:80%;font-size:12px;color:#657188;text-align:center;padding:6px 10px;background:#edf1f7;border-radius:999px}.composer{background:#fff;border-top:1px solid #e4e9f2;padding:12px 18px;display:flex;gap:8px;align-items:flex-end}.composer textarea{min-height:46px;max-height:130px;resize:vertical}.empty{padding:30px;color:#748098;text-align:center}.error{margin:10px 18px;padding:10px 12px;background:#ffe9eb;color:#8a1f2a;border-radius:9px;display:none}.loading{padding:14px;color:#748098}.send-failed{color:#a72b37;font-weight:600}.staff-actions{display:flex;gap:7px;align-items:center}.modal-backdrop{position:fixed;inset:0;background:rgba(20,30,50,.48);display:grid;place-items:center;padding:22px;z-index:20}.modal-card{width:min(760px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:16px;border:1px solid #dfe5ef;box-shadow:0 22px 60px rgba(12,25,48,.24);padding:22px}.modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:12px}.modal-head h2{margin:0 0 4px;font-size:20px}.staff-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.staff-grid .wide{grid-column:1/-1}.staff-feedback{display:none;margin:10px 0;padding:10px 12px;border-radius:9px}.staff-feedback.error-box{background:#ffe9eb;color:#8a1f2a}.staff-feedback.success-box{background:#e8f7ee;color:#176238}.staff-list{margin-top:20px;border-top:1px solid #e4e9f2;padding-top:14px}.staff-list-row{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1.5fr) auto auto minmax(130px,auto);gap:10px;padding:12px 0;border-bottom:1px solid #edf1f7;align-items:center}.staff-list-row .name{font-weight:700}.staff-list-row .email{font-size:13px;color:#59657c;overflow-wrap:anywhere}.status-dot{font-size:11px;border-radius:999px;padding:4px 7px;background:#e8f7ee;color:#176238}.status-dot.off{background:#f1f2f5;color:#6b7280}.status-dot.conflict{background:#fff0d8;color:#8a4b08}.staff-row-actions{display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap}.staff-row-actions .btn{padding:7px 9px;font-size:12px}.inline-check{display:flex;gap:8px;align-items:center;margin:14px 0}.inline-check input{width:auto}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.section-title{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:8px}
@media(max-width:950px){.app{grid-template-columns:300px 1fr}.content{grid-template-columns:1fr}.context{display:none}}@media(max-width:700px){.app{grid-template-columns:1fr}.sidebar{height:45vh}.main{height:55vh}.msg{max-width:92%}.staff-grid{grid-template-columns:1fr}.staff-grid .wide{grid-column:auto}.staff-list-row{grid-template-columns:1fr}.staff-row-actions{justify-content:flex-start}}
</style>
</head>
<body>
<section class="login-page" id="loginPage">
  <form class="login-card" id="loginForm">
    <h1>Customer Support</h1>
    <p>Sign in with your staff account.</p>
    <div class="field"><label for="email">Email</label><input id="email" type="email" autocomplete="username" required /></div>
    <div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required /></div>
    <button class="btn primary" id="loginBtn" type="submit">Sign in</button>
    <div class="login-error" id="loginError"></div>
  </form>
</section>
<div class="app hidden" id="dashboard">
  <aside class="sidebar">
    <div class="brand"><h1>Customer Support</h1><div class="muted">Shipment support dashboard</div></div>
    <div class="staffbar"><div class="muted" id="agentLabel"></div><div class="staff-actions"><button class="btn hidden" id="manageStaffBtn">Staff accounts</button><button class="btn" id="logoutBtn">Logout</button></div></div>
    <div class="tabs" id="tabs">
      <button data-view="unassigned" class="active">Unassigned</button><button data-view="mine">My tickets</button><button data-view="active">Active</button><button data-view="waiting">Waiting</button><button data-view="history">History</button>
    </div>
    <div class="queue" id="queue"><div class="empty">No tickets loaded.</div></div>
  </aside>
  <main class="main">
    <div class="header"><div><strong id="ticketTitle">Select a ticket</strong><div class="muted" id="ticketSubtitle"></div></div><div class="actions" id="actions"></div></div>
    <div class="error" id="error"></div>
    <div class="content"><section class="conversation" id="conversation"><div class="empty">Ticket conversation will appear here.</div></section><aside class="context" id="context"><div class="muted">Customer and escalation context will appear here.</div></aside></div>
    <div class="composer"><textarea id="message" dir="auto" placeholder="Reply to customer on WhatsApp" disabled></textarea><button class="btn primary" id="sendBtn" disabled>Send</button></div>
  </main>
</div>
<section class="modal-backdrop hidden" id="staffModal" role="dialog" aria-modal="true" aria-labelledby="staffModalTitle">
  <div class="modal-card">
    <div class="modal-head"><div><h2 id="staffModalTitle">Staff accounts</h2><div class="muted">Create, edit, deactivate, reactivate, reset passwords, and change agent/admin roles.</div></div><button class="btn" id="closeStaffBtn" type="button">Close</button></div>
    <div class="staff-feedback error-box" id="staffError"></div>
    <button class="btn hidden" id="editConflictStaffBtn" type="button">Edit the existing account</button>
    <div class="staff-feedback success-box" id="staffSuccess"></div>
    <form id="staffForm">
      <input id="staffEditingId" type="hidden" />
      <div class="section-title"><strong id="staffFormTitle">Create account</strong><button class="btn hidden" id="cancelStaffEditBtn" type="button">Cancel edit</button></div>
      <div class="staff-grid">
        <div class="field"><label for="staffName">Name</label><input id="staffName" type="text" maxlength="120" autocomplete="off" required /></div>
        <div class="field"><label for="staffEmail">Email</label><input id="staffEmail" type="email" maxlength="320" autocomplete="off" required /></div>
        <div class="field"><label for="staffRole">Role</label><select id="staffRole" required><option value="agent">Agent</option><option value="admin">Admin</option></select></div>
        <label class="inline-check hidden" id="staffActiveField"><input id="staffActive" type="checkbox" checked /> Account active</label>
        <div class="field"><label for="staffPassword" id="staffPasswordLabel">Initial password</label><input id="staffPassword" type="password" minlength="12" maxlength="72" autocomplete="new-password" required /></div>
        <div class="field"><label for="staffPasswordConfirm">Confirm password</label><input id="staffPasswordConfirm" type="password" minlength="12" maxlength="72" autocomplete="new-password" required /></div>
      </div>
      <div class="muted" id="staffPasswordHint">Minimum 12 characters and maximum 72 UTF-8 bytes. Passwords are never displayed or returned by the API.</div>
      <div class="modal-actions"><button class="btn primary" id="saveStaffBtn" type="submit">Create account</button></div>
    </form>
    <div class="staff-list"><div class="section-title"><strong>Existing staff</strong><button class="btn" id="refreshStaffBtn" type="button">Refresh</button></div><div id="staffList"><div class="loading">Loading…</div></div></div>
  </div>
</section>
<script>
const state={view:'unassigned',ticketId:null,agent:null,busy:false,authenticated:false,staffBusy:false,staffItems:[],editingStaffId:null,editingStaffOriginal:null,conflictStaff:null};
const $=id=>document.getElementById(id);
function cookie(name){return document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(name+'='))?.slice(name.length+1)||''}
function csrf(){return decodeURIComponent(cookie('__CSRF_COOKIE__'))}
function showLoginError(msg){const el=$('loginError');el.textContent=msg||'';el.style.display=msg?'block':'none'}
function showError(msg){const el=$('error');el.textContent=msg||'';el.style.display=msg?'block':'none'}
function showLogin(){state.authenticated=false;state.agent=null;state.staffItems=[];state.editingStaffId=null;$('dashboard').classList.add('hidden');$('loginPage').classList.remove('hidden');$('staffModal').classList.add('hidden');$('manageStaffBtn').classList.add('hidden');$('password').value=''}
function canManageStaff(){return Boolean(state.agent&&(state.agent.can_manage_staff||['supervisor','admin'].includes(state.agent.role)))}
function configureStaffAccess(){$('manageStaffBtn').classList.toggle('hidden',!canManageStaff())}
function showDashboard(){state.authenticated=true;$('loginPage').classList.add('hidden');$('dashboard').classList.remove('hidden');configureStaffAccess()}
async function api(path,options={}){const headers={...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';if(options.method&&options.method!=='GET')headers['X-CSRF-Token']=csrf();const r=await fetch(path,{credentials:'same-origin',...options,headers});let data={};try{data=await r.json()}catch{}if(r.status===401&&path!=='/api/support/login'){showLogin();throw new Error('Your staff session expired. Please sign in again.')}if(!r.ok){const detail=data.detail;const message=typeof detail==='string'?detail:(detail&&detail.message)||('Request failed ('+r.status+')');const error=new Error(message);error.detail=detail;error.status=r.status;throw error}return data}
function text(el,value){el.textContent=value??''}
function fmt(v){if(!v)return '—';try{return new Date(v).toLocaleString()}catch{return String(v)}}
async function login(e){e.preventDefault();if(state.busy)return;state.busy=true;$('loginBtn').disabled=true;showLoginError('');try{state.agent=await api('/api/support/login',{method:'POST',body:JSON.stringify({email:$('email').value.trim(),password:$('password').value})});text($('agentLabel'),state.agent.name+' · '+state.agent.role);showDashboard();await loadQueue()}catch(err){showLoginError(err.message)}finally{state.busy=false;$('loginBtn').disabled=false}}
async function bootstrap(){try{state.agent=await api('/api/support/me');text($('agentLabel'),state.agent.name+' · '+state.agent.role);showDashboard();await loadQueue()}catch{showLogin()}}
async function logout(){if(state.busy)return;state.busy=true;try{await api('/api/support/logout',{method:'POST'});}catch{}finally{state.busy=false;showLogin()}}
function showStaffFeedback(id,msg){const el=$(id);el.textContent=msg||'';el.style.display=msg?'block':'none'}
function resetStaffForm(){state.editingStaffId=null;state.editingStaffOriginal=null;state.conflictStaff=null;$('staffEditingId').value='';$('staffForm').reset();$('staffRole').value='agent';$('staffActive').checked=true;$('staffActiveField').classList.add('hidden');$('staffPassword').required=true;$('staffPasswordConfirm').required=true;$('staffPasswordLabel').textContent='Initial password';$('staffPasswordHint').textContent='Minimum 12 characters and maximum 72 UTF-8 bytes. Passwords are never displayed or returned by the API.';$('staffFormTitle').textContent='Create account';$('saveStaffBtn').textContent='Create account';$('cancelStaffEditBtn').classList.add('hidden');$('editConflictStaffBtn').classList.add('hidden')}
function closeStaffModal(){$('staffModal').classList.add('hidden');showStaffFeedback('staffError','');showStaffFeedback('staffSuccess','');resetStaffForm()}
async function openStaffModal(){if(!canManageStaff())return;$('staffModal').classList.remove('hidden');showStaffFeedback('staffError','');showStaffFeedback('staffSuccess','');resetStaffForm();await loadStaffAccounts()}
function beginStaffEdit(item){if(!item||item.role==='supervisor')return;state.editingStaffId=String(item.id);state.editingStaffOriginal={...item};$('staffEditingId').value=String(item.id);$('staffName').value=item.name||'';$('staffEmail').value=item.email||'';$('staffRole').value=item.role==='admin'?'admin':'agent';$('staffActive').checked=Boolean(item.is_active);$('staffActiveField').classList.remove('hidden');$('staffPassword').value='';$('staffPasswordConfirm').value='';$('staffPassword').required=false;$('staffPasswordConfirm').required=false;$('staffPasswordLabel').textContent='New password (optional)';$('staffPasswordHint').textContent='Leave the password blank to keep it unchanged. Credential, role, or activation changes revoke the account’s current sessions.';$('staffFormTitle').textContent='Edit '+(item.name||item.email||'account');$('saveStaffBtn').textContent='Save changes';$('cancelStaffEditBtn').classList.remove('hidden');$('editConflictStaffBtn').classList.add('hidden');showStaffFeedback('staffError','');showStaffFeedback('staffSuccess','');$('staffName').focus()}
function staffButton(label,handler,cls=''){const button=document.createElement('button');button.type='button';button.className='btn '+cls;button.textContent=label;button.onclick=handler;return button}
function renderStaffAccounts(items){state.staffItems=items||[];const box=$('staffList');box.innerHTML='';if(!state.staffItems.length){box.innerHTML='<div class="empty">No staff accounts found.</div>';return}for(const item of state.staffItems){const row=document.createElement('div');row.className='staff-list-row';const who=document.createElement('div');const name=document.createElement('div');name.className='name';name.textContent=item.name||'Unnamed';const created=document.createElement('div');created.className='muted';created.textContent='Created '+fmt(item.created_at);who.append(name,created);const email=document.createElement('div');email.className='email';email.textContent=item.email||'—';const role=document.createElement('span');role.className='badge';role.textContent=item.role||'—';const active=document.createElement('span');active.className='status-dot'+(item.is_active?'':' off');active.textContent=item.is_active?'Active':'Inactive';if(item.email_conflict){const conflict=document.createElement('span');conflict.className='status-dot conflict';conflict.textContent='Duplicate email';who.append(conflict)}const actions=document.createElement('div');actions.className='staff-row-actions';if(item.role!=='supervisor'){actions.append(staffButton('Edit',()=>beginStaffEdit(item)));actions.append(staffButton(item.is_active?'Delete':'Edit / reactivate',item.is_active?()=>deleteStaffAccount(item):()=>beginStaffEdit(item),item.is_active?'danger':''))}else{const protectedLabel=document.createElement('span');protectedLabel.className='muted';protectedLabel.textContent='Protected';actions.append(protectedLabel)}row.append(who,email,role,active,actions);box.append(row)}}
async function loadStaffAccounts(){if(!canManageStaff())return;const box=$('staffList');box.innerHTML='<div class="loading">Loading…</div>';try{const data=await api('/api/support/staff');renderStaffAccounts(data.items||[])}catch(e){box.innerHTML='<div class="empty">Could not load staff accounts.</div>';showStaffFeedback('staffError',e.message)}}
function handleStaffConflict(error){const detail=error&&error.detail;if(detail&&detail.code==='email_conflict'&&detail.existing_staff){state.conflictStaff=detail.existing_staff;showStaffFeedback('staffError',detail.message||error.message);$('editConflictStaffBtn').classList.remove('hidden');return true}return false}
async function saveStaffAccount(e){e.preventDefault();if(state.staffBusy||!canManageStaff())return;showStaffFeedback('staffError','');showStaffFeedback('staffSuccess','');$('editConflictStaffBtn').classList.add('hidden');const password=$('staffPassword').value;const confirmation=$('staffPasswordConfirm').value;if(password!==confirmation){showStaffFeedback('staffError','Passwords do not match.');return}const editing=Boolean(state.editingStaffId);if(!editing&&!password){showStaffFeedback('staffError','An initial password is required.');return}const name=$('staffName').value.trim(),email=$('staffEmail').value.trim(),role=$('staffRole').value,active=$('staffActive').checked;let payload={};if(editing){const original=state.editingStaffOriginal||{};if(name!==(original.name||''))payload.name=name;if(email!==(original.email||''))payload.email=email;if(role!==(original.role||''))payload.role=role;if(active!==Boolean(original.is_active))payload.is_active=active;if(password)payload.password=password;if(!Object.keys(payload).length){showStaffFeedback('staffError','No changes to save.');return}}else{payload={name,email,role,password}}state.staffBusy=true;$('saveStaffBtn').disabled=true;try{const path=editing?'/api/support/staff/'+encodeURIComponent(state.editingStaffId):'/api/support/staff';const data=await api(path,{method:editing?'PATCH':'POST',body:JSON.stringify(payload)});const action=editing?'Updated ':'Created ';showStaffFeedback('staffSuccess',action+data.staff.name+' ('+data.staff.role+').');const sessionRevoked=Boolean(data.staff.current_session_revoked);resetStaffForm();await loadStaffAccounts();if(sessionRevoked){alert('Your credentials changed, so this staff session was revoked. Please sign in again.');showLogin()}}catch(e){if(!handleStaffConflict(e))showStaffFeedback('staffError',e.message)}finally{state.staffBusy=false;$('saveStaffBtn').disabled=false;$('staffPassword').value='';$('staffPasswordConfirm').value=''}}
async function deleteStaffAccount(item){if(state.staffBusy||!item)return;if(String(item.id)===String(state.agent&&state.agent.id)){showStaffFeedback('staffError','You cannot delete your own active account.');return}if(!confirm('Delete this staff account? It will be deactivated and all of its sessions will be revoked.'))return;state.staffBusy=true;try{await api('/api/support/staff/'+encodeURIComponent(item.id),{method:'DELETE'});showStaffFeedback('staffSuccess','Deleted '+(item.name||item.email)+'.');if(state.editingStaffId===String(item.id))resetStaffForm();await loadStaffAccounts()}catch(e){showStaffFeedback('staffError',e.message)}finally{state.staffBusy=false}}
async function loadQueue(){if(!state.authenticated)return;const q=$('queue');q.innerHTML='<div class="loading">Loading…</div>';try{const data=await api('/api/support/tickets?view='+encodeURIComponent(state.view));q.innerHTML='';if(!data.items.length){q.innerHTML='<div class="empty">No tickets in this queue.</div>';return}for(const t of data.items){const row=document.createElement('div');row.className='ticket-row'+(state.ticketId===t.id?' active':'');row.onclick=()=>openTicket(t.id);const top=document.createElement('div');top.className='top';const strong=document.createElement('strong');strong.textContent=t.ticket_reference;const badge=document.createElement('span');badge.className='badge';badge.textContent=t.status;top.append(strong,badge);const who=document.createElement('div');who.className='muted';who.textContent=t.customer_name||t.customer_userid||t.whatsapp_phone;const sum=document.createElement('div');sum.className='summary';sum.dir='auto';sum.textContent=t.ai_summary||t.reason;row.append(top,who,sum);q.append(row)}}catch(e){q.innerHTML='<div class="empty">Could not load queue.</div>';showError(e.message)}}
function addMessage(container,m,extraClass=''){const div=document.createElement('div');div.className='msg '+(m.direction==='OUTBOUND'?'out ':'')+extraClass;const body=document.createElement('div');body.dir='auto';body.textContent=m.body||m.content||'';const meta=document.createElement('div');meta.className='meta';meta.textContent=(m.sender_name||m.sender_type||m.role||'')+' · '+fmt(m.created_at||'');if(m.send_status==='FAILED'){const fail=document.createElement('span');fail.className='send-failed';fail.textContent=' · send failed'+(m.error_message?': '+m.error_message:'');meta.append(fail)}else if(m.send_status==='PENDING'){meta.append(document.createTextNode(' · sending…'))}div.append(body,meta);container.append(div)}
function addEvent(container,e){const div=document.createElement('div');div.className='event';div.textContent=(e.event_type||'EVENT').replaceAll('_',' ')+' · '+(e.actor_name||e.actor_type||'SYSTEM')+' · '+fmt(e.created_at);container.append(div)}
function renderContext(ticket,ctx,shipment){const c=$('context');c.innerHTML='';const groups=[['Customer',[['Name',ticket.customer_name],['Userid',ticket.customer_userid],['Customer ID',ticket.customer_id],['WhatsApp',ticket.whatsapp_phone],['Language',ticket.current_language],['Style',ticket.communication_style]]],['Escalation',[['Reason',ticket.reason],['AI summary',ticket.ai_summary],['Tracking',ticket.tracking_reference],['Requested action',ticket.requested_action]]],['Shipment',[['Status',shipment&&shipment.status],['Mode',shipment&&shipment.mode],['Description',shipment&&shipment.description],['Order ID',shipment&&shipment.order_id],['Shipment ID',shipment&&shipment.shipment_id]]],['Ticket',[['Status',ticket.status],['Assignee',ticket.current_assignee_name],['Created',fmt(ticket.created_at)],['Last activity',fmt(ticket.last_activity_at)]]]];for(const [title,items] of groups){const h=document.createElement('h3');h.textContent=title;c.append(h);for(const [label,value] of items){const p=document.createElement('p');p.dir='auto';const b=document.createElement('strong');b.textContent=label+': ';p.append(b,document.createTextNode(value??'—'));c.append(p)}}}
function actionButton(label,fn,cls=''){const b=document.createElement('button');b.className='btn '+cls;b.textContent=label;b.disabled=state.busy;b.onclick=fn;return b}
async function openTicket(id){state.ticketId=id;showError('');try{const data=await api('/api/support/tickets/'+id);const t=data.ticket;text($('ticketTitle'),t.ticket_reference+' · '+t.status);text($('ticketSubtitle'),t.customer_name||t.customer_userid||t.whatsapp_phone);renderContext(t,data.context||{},data.shipment||null);const conv=$('conversation');conv.innerHTML='';const pre=((data.context||{}).recent_messages||[]).filter(m=>['user','assistant'].includes(m.role)&&m.content);const firstInbound=(data.messages||[]).find(m=>m.sender_type==='CUSTOMER'&&m.direction==='INBOUND');if(firstInbound&&pre.length&&pre[pre.length-1].role==='user'&&pre[pre.length-1].content===firstInbound.body)pre.pop();for(const m of pre){addMessage(conv,{body:m.content,sender_type:m.role==='user'?'CUSTOMER':'AI',direction:m.role==='user'?'INBOUND':'OUTBOUND'},'context-msg')}const timeline=[...(data.messages||[]).map(x=>({kind:'message',at:x.created_at,data:x})),...(data.events||[]).map(x=>({kind:'event',at:x.created_at,data:x}))].sort((a,b)=>String(a.at||'').localeCompare(String(b.at||'')));for(const item of timeline){if(item.kind==='message')addMessage(conv,item.data);else addEvent(conv,item.data)}conv.scrollTop=conv.scrollHeight;renderActions(data);$('message').disabled=!data.permissions.can_operate||!t.active_key;$('sendBtn').disabled=$('message').disabled;await loadQueue()}catch(e){showError(e.message)}}
function renderActions(data){const box=$('actions');box.innerHTML='';const t=data.ticket,p=data.permissions;if(p.can_claim)box.append(actionButton('Claim',()=>doAction('/claim')));if(p.can_operate&&t.active_key){for(const s of ['IN_PROGRESS','WAITING_CUSTOMER','WAITING_INTERNAL']){if(s!==t.status)box.append(actionButton(s.replaceAll('_',' '),()=>setStatus(s)))}box.append(actionButton('Resolve & return to AI',resolveTicket,'danger'))}}
async function doAction(suffix){if(state.busy)return;state.busy=true;let ok=false;try{await api('/api/support/tickets/'+state.ticketId+suffix,{method:'POST'});ok=true}catch(e){showError(e.message)}finally{state.busy=false}if(ok)await openTicket(state.ticketId)}
async function setStatus(s){if(state.busy)return;state.busy=true;let ok=false;try{await api('/api/support/tickets/'+state.ticketId+'/status',{method:'POST',body:JSON.stringify({status:s})});ok=true}catch(e){showError(e.message)}finally{state.busy=false}if(ok)await openTicket(state.ticketId)}
async function resolveTicket(){if(!confirm('Resolve this ticket and return the WhatsApp conversation to AI?'))return;await doAction('/resolve')}
async function sendMessage(){const body=$('message').value.trim();if(!body||state.busy)return;state.busy=true;$('sendBtn').disabled=true;const id=crypto.randomUUID();let refresh=false;try{await api('/api/support/tickets/'+state.ticketId+'/messages',{method:'POST',body:JSON.stringify({body,client_message_id:id})});$('message').value='';refresh=true}catch(e){showError(e.message);refresh=true}finally{state.busy=false;$('sendBtn').disabled=false}if(refresh)await openTicket(state.ticketId)}
$('loginForm').addEventListener('submit',login);$('logoutBtn').onclick=logout;$('manageStaffBtn').onclick=openStaffModal;$('closeStaffBtn').onclick=closeStaffModal;$('refreshStaffBtn').onclick=loadStaffAccounts;$('cancelStaffEditBtn').onclick=resetStaffForm;$('editConflictStaffBtn').onclick=()=>{if(state.conflictStaff)beginStaffEdit(state.conflictStaff)};$('staffForm').addEventListener('submit',saveStaffAccount);$('staffModal').addEventListener('click',e=>{if(e.target===$('staffModal'))closeStaffModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('staffModal').classList.contains('hidden'))closeStaffModal()});$('sendBtn').onclick=sendMessage;$('message').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});$('tabs').onclick=e=>{const b=e.target.closest('button[data-view]');if(!b)return;state.view=b.dataset.view;state.ticketId=null;for(const x of $('tabs').querySelectorAll('button'))x.classList.toggle('active',x===b);loadQueue()};
bootstrap();setInterval(()=>{if(state.authenticated&&!state.busy){if(state.ticketId)openTicket(state.ticketId);else loadQueue()}},__POLL_MS__);
</script>
</body></html>'''
